// Gauss filter family executor: nppiFilterGauss / GaussBorder /
// GaussAdvanced / GaussAdvancedBorder.
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_filter_gauss_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_filter_gauss*.json).
//
// Semantics (baseline NVIDIA NPP 13.4 on RTX 5090, probe-verified; see
// tools/probe_f10/fit/gauss_arith.cu and gauss_arith.out):
//   * nppiFilterGauss accepts the square mask sizes 3,5,7,9,11,13,15.  The 1D
//     kernel is a normalised Gaussian with sigma = 0.6 + 0.4 * (taps/2); the
//     2D kernel is its outer product, evaluated with the kernel origin at
//     (taps-1)/2 (correlation, i.e. dst(x)=sum_i k[i]*src(x-a+i)).
//   * nppiFilterGaussAdvanced takes an odd nFilterTaps >= 3 and a user 1D
//     kernel pKernel; the 2D kernel is the outer product (unnormalised) and
//     the same correlation geometry applies.
//   * Plain variants read raw pixels around pSrc with no clamping (the caller
//     must provide a margin); border variants support NPP_BORDER_REPLICATE
//     only and clamp the read coordinates to the source image bounds relative
//     to pSrc: [-offX, srcW-1-offX] x [-offY, srcH-1-offY].
//   * Accumulation is float32 with fused multiply-add; integer destinations
//     truncate toward zero and saturate: 8u [0,255], 16u [0,65535],
//     16s [-32768,32767].  32f stores the accumulator unchanged.
//   * AC4 (AlphaPreserve=true) computes channels 0..2 only and never writes the
//     alpha channel of pDst; C4 computes all four channels.
//   * Validation order, plain Gauss: null -> negative ROI (SIZE_ERROR) ->
//     unsupported eMaskSize (MASK_SIZE_ERROR) -> zero-size ROI (NO_ERROR) ->
//     dst step (STEP_ERROR / NOT_EVEN_STEP_ERROR).
//   * Validation order, GaussBorder: null -> negative ROI -> oSrcSize <= 0
//     (SIZE_ERROR) -> oSrcOffset out of range (OUT_OFF_RANGE_ERROR) ->
//     unsupported border type (NOT_SUPPORTED_MODE_ERROR) -> eMaskSize ->
//     zero-size ROI -> dst step.
//   * Validation order, GaussAdvanced (plain): null (src/dst/kernel) ->
//     negative ROI -> zero-size ROI quirks (nFilterTaps <= 0 -> SIZE_ERROR,
//     nFilterTaps < 3 -> MASK_SIZE_ERROR, otherwise NO_ERROR regardless of
//     parity) -> negative taps (BAD_ARGUMENT_ERROR) -> taps < 3 or even
//     (MASK_SIZE_ERROR) -> dst step.
//   * Validation order, GaussAdvancedBorder: null -> negative ROI ->
//     oSrcSize <= 0 -> oSrcOffset out of range -> border type -> taps
//     (negative, < 3 or even all MASK_SIZE_ERROR) -> zero-size ROI -> dst
//     step.
//   * Dst step checks are unsigned (a negative step passes) and require a
//     multiple of the alignment (element size for C1/C3, pixel size for
//     C4/AC4).  The source step is never validated.
#ifndef NPPI_FILTER_GAUSS_EXECUTOR_H
#define NPPI_FILTER_GAUSS_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace filter {

template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus filterGauss(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI,
                      NppiMaskSize eMaskSize, cudaStream_t stream);

template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus filterGaussBorder(const Src *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset, Dst *pDst,
                            int nDstStep, NppiSize oSizeROI, NppiMaskSize eMaskSize, NppiBorderType eBorderType,
                            cudaStream_t stream);

template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus filterGaussAdvanced(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI,
                              int nFilterTaps, const Npp32f *pKernel, cudaStream_t stream);

template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus filterGaussAdvancedBorder(const Src *pSrc, int nSrcStep, NppiSize oSrcSize, NppiPoint oSrcOffset,
                                    Dst *pDst, int nDstStep, NppiSize oSizeROI, int nFilterTaps,
                                    const Npp32f *pKernel, NppiBorderType eBorderType, cudaStream_t stream);

}  // namespace filter
}  // namespace nppi

#endif  // NPPI_FILTER_GAUSS_EXECUTOR_H
